import { z } from "zod";
import data from "./catalog.json" with { type: "json" };
import type { Catalog } from "./types.ts";

const CatalogSchema = z.object({
  generatedAt: z.string(),
  tokens: z.array(
    z.object({
      symbol: z.string(),
      name: z.string(),
      issuer: z.string(),
      mint: z.string(),
      decimals: z.number().int().nonnegative(),
      redeemable: z.enum(["share_redeemable", "cash_redeemable", "not_redeemable"]).nullable(),
    }),
  ),
});

export const parseCatalog = (raw: unknown): Catalog => CatalogSchema.parse(raw);

// generated by `npm run catalog`, checked once at startup: a broken file fails loudly instead of quoting the wrong token
export const CATALOG = parseCatalog(data);
